1	package indexroom
2	
3	import (
4		"math"
5		"strconv"
6		"strings"
7		"testing"
8	)
9	
10	// TestParseExpectedRevision locks the raw-token parser shared by every request
11	// kind. It establishes integer type only; the architecture-specific upper
12	// bound is enforced later by validateExpectedRevision, so negatives still parse
13	// here and are rejected at validation.
14	func TestParseExpectedRevision(t *testing.T) {
15		cases := []struct {
16			text string
17			want int64
18			err  string // "" means no error expected
19		}{
20			{"0", 0, ""},
21			{"1", 1, ""},
22			{"2147483647", 2147483647, ""},
23			{"2147483648", 2147483648, ""},
24			{"9223372036854775807", 9223372036854775807, ""},
25			// Negatives parse as integers; the non-negative rule belongs to the
26			// range check so its reason can state the full range.
27			{"-1", -1, ""},
28			{"-4294967295", -4294967295, ""},
29			// Non-integer tokens get the integer-type error, quoting as submitted.
30			{"1.5", 0, "expectedRevision must be an integer, got 1.5"},
31			{"1e3", 0, "expectedRevision must be an integer, got 1e3"},
32			{`"1"`, 0, "expectedRevision must be an integer"},
33			{"true", 0, "expectedRevision must be an integer"},
34			// A decimal point or exponent makes the token non-integer notation
35			// regardless of its value: even an integer part too long for int64
36			// (18446744073709551616 is 2^64) and an exponent whose value is below 1
37			// stay an integer-format rejection with the submitted text, never a
38			// range error or an accepted conversion.
39			{"18446744073709551616.0", 0, "expectedRevision must be an integer, got 18446744073709551616.0"},
40			{"18446744073709551616e-20", 0, "expectedRevision must be an integer, got 18446744073709551616e-20"},
41			{"-18446744073709551616e-20", 0, "expectedRevision must be an integer, got -18446744073709551616e-20"},
42			{"18446744073709551616E0", 0, "expectedRevision must be an integer, got 18446744073709551616E0"},
43			// Exponent notation that happens to equal an in-range integer is still
44			// the wrong notation; it must not parse to that integer.
45			{"9223372036854775807e0", 0, "expectedRevision must be an integer, got 9223372036854775807e0"},
46			// Pure integer notation above int64 keeps the range reason: the digits
47			// carry no decimal point or exponent, so the value is simply too large.
48			{"9223372036854775808", 0, "expectedRevision must be an integer between 0 and"},
49			{"-9223372036854775809", 0, "expectedRevision must be an integer between 0 and"},
50		}
51		for _, tc := range cases {
52			t.Run(tc.text, func(t *testing.T) {
53				got, err := ParseExpectedRevision(tc.text)
54				if tc.err == "" {
55					if err != nil {
56						t.Fatalf("unexpected error: %v", err)
57					}
58					if got != tc.want {
59						t.Fatalf("got %d want %d", got, tc.want)
60					}
61					return
62				}
63				if err == nil || !strings.Contains(err.Error(), tc.err) {
64					t.Fatalf("got error %v, want substring %q", err, tc.err)
65				}
66			})
67		}
68	}
69	
70	// revisionRangeBound is the accepted upper bound for the test build's
71	// architecture, mirroring maxRevision.
72	func revisionRangeBound() int64 {
73		if strconv.IntSize == 32 {
74			return math.MaxInt32
75		}
76		return math.MaxInt64
77	}
78	
79	// TestValidateExpectedRevisionRange checks the raw int64 value before it is
80	// narrowed to int. The decisive case only exists on a 32-bit build: values that
81	// fit int64 but wrap when converted to int (4294967297 -> 1) must be rejected.
82	// On a 64-bit build that value is a legitimate integer and proceeds to the
83	// ordinary revision comparison.
84	func TestValidateExpectedRevisionRange(t *testing.T) {
85		bound := revisionRangeBound()
86	
87		if err := validateExpectedRevision(0); err != nil {
88			t.Fatalf("0 should be valid: %v", err)
89		}
90		if err := validateExpectedRevision(bound); err != nil {
91			t.Fatalf("upper bound %d should be valid: %v", bound, err)
92		}
93	
94		wantRange := func(t *testing.T, err error) {
95			t.Helper()
96			if err == nil {
97				t.Fatalf("expected an invalid error")
98			}
99			msg := err.Error()
100			if !strings.Contains(msg, "expectedRevision must be an integer between 0 and") {
101				t.Fatalf("reason should state the expectedRevision range, got %q", msg)
102			}
103			if !strings.Contains(msg, "got ") {
104				t.Fatalf("reason should report the submitted value, got %q", msg)
105			}
106		}
107	
108		// Negatives are invalid on every architecture with the range reason.
109		wantRange(t, validateExpectedRevision(-1))
110	
111		if strconv.IntSize == 32 {
112			// The two wrapping values from the bug report must not reach the
113			// revision comparison as 1; the integer just above the bound is the
114			// smallest value int cannot carry.
115			for _, n := range []int64{4294967297, -4294967295, bound + 1} {
116				wantRange(t, validateExpectedRevision(n))
117			}
118		}
119	}
120	
121	// TestRegistrationRejectsOutOfRangeRawRevision drives all three Validate*
122	// entry points with a raw int64 the architecture's int cannot represent. On a
123	// 32-bit build every one must fail validation (returning its zero value) before
124	// any revision comparison, so the caller can never Apply, ApplyHealth or
125	// Select with a wrapped revision.
126	func TestRegistrationRejectsOutOfRangeRawRevision(t *testing.T) {
127		if strconv.IntSize != 32 {
128			// On 64-bit int64 cannot express an in-type overflow; the
129			// beyond-int64 raw text is covered through ParseExpectedRevision and
130			// the command-level tests.
131			t.Skip("raw int64 overflow of int is only constructible on a 32-bit build")
132		}
133		r := NewRegistry()
134		reg, _ := r.ValidateRegistration("svc", 0, []Instance{{ID: "i1", Address: "h1:1"}})
135		r.Apply(reg)
136		upd0, _ := r.ValidateHealth("svc", "i1", 1, 1, true, "")
137		r.ApplyHealth(upd0)
138	
139		for _, n := range []int64{4294967297, -4294967295} {
140			if reg, err := r.ValidateRegistration("svc", n, []Instance{{ID: "i1", Address: "h9:9"}}); err == nil {
141				t.Fatalf("register revision %d should be invalid, got %+v", n, reg)
142			} else if reg.Service != "" || reg.Revision != 0 || reg.Instances != nil {
143				t.Fatalf("failed register validation returned a partial value: %+v", reg)
144			}
145			if upd, err := r.ValidateHealth("svc", "i1", n, 2, true, ""); err == nil {
146				t.Fatalf("health revision %d should be invalid, got %+v", n, upd)
147			}
148			if sel, err := r.ValidateSelection("svc", n); err == nil {
149				t.Fatalf("select revision %d should be invalid, got %+v", n, sel)
150			}
151			if sel, err := r.ValidateSelectionWithSession("svc", n, strPtr("s")); err == nil {
152				t.Fatalf("session select revision %d should be invalid, got %+v", n, sel)
153			}
154		}
155	
156		// Nothing the rejected items proposed took effect: revision, address and
157		// health all stand at the state established beforehand.
158		views := r.Snapshot()
159		if len(views) != 1 || views[0].Revision != 1 {
160			t.Fatalf("state changed after rejected raw revisions: %+v", views)
161		}
162		inst := views[0].Instances[0]
163		if inst.Address != "h1:1" || inst.Health != HealthHealthy || inst.Sequence != 1 {
164			t.Fatalf("rejected raw revisions must not change state: %+v", inst)
165		}
166	}
167	
168	// TestInRangeLargeRevisionKeepsConflictSemantics locks the 64-bit behavior:
169	// 2147483648 is a perfectly legal integer there, so for a service at revision
170	// 1 it must pass validation and produce an ordinary conflict carrying the
171	// original expected value — the fix must not clamp 64-bit to the 32-bit bound.
172	func TestInRangeLargeRevisionKeepsConflictSemantics(t *testing.T) {
173		r := NewRegistry()
174		reg, _ := r.ValidateRegistration("svc", 0, []Instance{{ID: "i1", Address: "h1:1"}})
175		r.Apply(reg)
176	
177		// large is a variable so narrowing it to int is a runtime conversion that
178		// only executes on the 64-bit path.
179		large := int64(2147483648)
180		if strconv.IntSize == 32 {
181			if _, err := r.ValidateRegistration("svc", large, nil); err == nil {
182				t.Fatalf("2147483648 must be out of range on a 32-bit build")
183			}
184			if _, err := r.ValidateSelection("svc", large); err == nil {
185				t.Fatalf("2147483648 select must be out of range on a 32-bit build")
186			}
187			return
188		}
189	
190		reg, err := r.ValidateRegistration("svc", large, nil)
191		if err != nil {
192			t.Fatalf("2147483648 should validate on 64-bit: %v", err)
193		}
194		if out := r.Apply(reg); out.OK || out.Kind != OutcomeConflict ||
195			out.Expected != int(large) || out.Actual != 1 || out.Revision != 1 {
196			t.Fatalf("large in-range revision should conflict preserving the value: %+v", out)
197		}
198		sel, err := r.ValidateSelection("svc", large)
199		if err != nil {
200			t.Fatalf("select validation: %v", err)
201		}
202		if out := r.Select(sel); out.OK || out.Kind != OutcomeConflict ||
203			out.Expected != int(large) || out.Actual != 1 {
204			t.Fatalf("large in-range select should conflict preserving the value: %+v", out)
205		}
206	}
