	registerService(t, r, "svc", 2, []Instance{{ID: "a", Address: "h1:1"}, {ID: "b", Address: "h2:2"}})
	markHealth(t, r, "svc", "a", 3, 1, true, "")
	if out := selectedWithSession(t, r, "svc", 3, "s"); out.InstanceID != "b" {
