		{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":3,"healthy":true},
		{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s1"},
		{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s1"},
		{"type":"select","service":"svc","expectedRevision":1},
